if item_category == "footwear":
    if price <= 500:
        gst_percent = 5
    else:
        gst_percent = 18
elif item_category == "apparels":
    if price <= 1000:
        gst_percent = 5
    else:
        gst_percent = 12
else:
    print("Invalid Category entered.")

if gst_percent > 0:
    cgst_rate = gst_percent / 2
    sgst_rate = gst_percent / 2
    tax_amount = (price * gst_percent) / 100
    total_price = price + tax_amount
